package com.pa.lcr.lcp;
import com.hoho.android.usbserial.driver.UsbSerialPort; public class LcpLink { public static boolean DUMP_TX=false,DUMP_RX=false; private final UsbSerialPort port; private final int to,from; private final boolean syncFirst; private int msgId=0; private boolean syncUsed=false; public LcpLink(UsbSerialPort port,int toAddr,int fromAddr,boolean syncFirst){ this.port=port; this.to=toAddr&0xFF; this.from=fromAddr&0xFF; this.syncFirst=syncFirst; } private int nextStatus(){ int st=msgId&0x01; if(syncFirst&&!syncUsed){ st=0x02; syncUsed=true;} msgId^=0x01; return st&0xFF; } private static byte[] concat(byte[]a,byte[]b){ byte[] r=new byte[a.length+b.length]; System.arraycopy(a,0,r,0,a.length); System.arraycopy(b,0,r,a.length,b.length); return r;} public byte[] buildFrame(byte[] p){ int st=nextStatus(); byte[] header=new byte[]{(byte)to,(byte)from,(byte)st,(byte)(p.length&0xFF)}; byte[] var=concat(header,p); byte[] varEsc=CrcLcp.escape(var); int crc=CrcLcp.crcLcp(varEsc); byte[] cRaw=new byte[]{(byte)(crc&0xFF),(byte)((crc>>>8)&0xFF)}; byte[] cEsc=CrcLcp.escape(cRaw); return concat(new byte[]{(byte)CrcLcp.TILDE,(byte)CrcLcp.TILDE}, concat(varEsc,cEsc)); } public byte[] sendRecv(byte[] payload,int timeoutMs) throws Exception { byte[] frm=buildFrame(payload); synchronized(port){ port.purgeHwBuffers(true,true); port.write(frm, timeoutMs);} return readFrame(timeoutMs);} public byte[] readFrame(int timeoutMs) throws Exception { long t0=System.currentTimeMillis(); int sync=0; byte[] b=new byte[1]; while(System.currentTimeMillis()-t0<timeoutMs){ int n=port.read(b,50); if(n<=0) continue; int v=b[0]&0xFF; if(v==CrcLcp.TILDE){ if(++sync==2) break;} else sync=0;} if(sync<2) throw new java.util.concurrent.TimeoutException("Sync ~~ timeout"); class R{ byte[] raw; boolean ok;} java.util.function.Supplier<R> r1=()->{ try{ byte[] bb=new byte[1]; int n=port.read(bb,100); if(n<=0) return r(null,false); int v=bb[0]&0xFF; if(v==CrcLcp.ESC){ byte[] y=new byte[1]; int m=port.read(y,100); if(m<=0) return r(null,false); return r(new byte[]{(byte)CrcLcp.ESC,y[0]},true);} return r(new byte[]{bb[0]},true);}catch(Exception e){ return r(null,false);} }; java.io.ByteArrayOutputStream rawHdr=new java.io.ByteArrayOutputStream(); byte[] hdr=new byte[4]; int hpos=0; while(hpos<4 && System.currentTimeMillis()-t0<timeoutMs){ R rr=r1.get(); if(!rr.ok) continue; hdr[hpos++]=rr.raw[rr.raw.length-1]; rawHdr.write(rr.raw,0,rr.raw.length);} if(hpos<4) throw new java.util.concurrent.TimeoutException("Header timeout"); int plen=hdr[3]&0xFF; java.io.ByteArrayOutputStream rawData=new java.io.ByteArrayOutputStream(); byte[] data=new byte[plen]; int dpos=0; while(dpos<plen && System.currentTimeMillis()-t0<timeoutMs){ R rr=r1.get(); if(!rr.ok) continue; data[dpos++]=rr.raw[rr.raw.length-1]; rawData.write(rr.raw,0,rr.raw.length);} if(dpos<plen) throw new java.util.concurrent.TimeoutException("Payload timeout"); byte[] crcB=new byte[2]; int cpos=0; while(cpos<2 && System.currentTimeMillis()-t0<timeoutMs){ R rr=r1.get(); if(!rr.ok) continue; crcB[cpos++]=rr.raw[rr.raw.length-1]; } if(cpos<2) throw new java.util.concurrent.TimeoutException("CRC timeout"); int calc=CrcLcp.crcLcp(concat(rawHdr.toByteArray(), rawData.toByteArray())); int recv=(crcB[0]&0xFF)|((crcB[1]&0xFF)<<8); if(calc!=recv) throw new IllegalStateException("CRC mismatch"); return concat(new byte[]{(byte)CrcLcp.TILDE,(byte)CrcLcp.TILDE}, concat(hdr, concat(data, crcB))); } private static R r(byte[] raw,boolean ok){ R o=new R(); o.raw=raw; o.ok=ok; return o;} public static int extractStatus(byte[] frame){ return frame[4]&0xFF;} public static byte[] extractPayload(byte[] frame){ int ln=frame[5]&0xFF; byte[] p=new byte[ln]; System.arraycopy(frame,6,p,0,ln); return p; }}
